inputs.script:
// Airtable Automation input variable required: recordId
// Trigger when Status or Approve Purchase changes.

const { recordId } = input.config();

if (!recordId || !/^rec[a-zA-Z0-9]{14,}$/.test(recordId)) {
    throw new Error("A valid Airtable recordId is required");
}

const webhookUrl = "https://n8n.dulcy.io/webhook/REDACTED_PATH";

const response = await fetch(webhookUrl, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({
        recordId,
        secret: "REDACTED_SECRET",
        source: "airtable",
    }),
});

if (!response.ok) {
    const detail = await response.text();
    throw new Error(`n8n webhook failed (${response.status}): ${detail}`);
}

output.set("sentRecordId", recordId);
